#include "motion_profile_storage.h"
#include "cJSON.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static const cJSON *item(const cJSON *o,const char *n){return o?cJSON_GetObjectItemCaseSensitive(o,n):NULL;}
static bool keys(const cJSON *o,const char *const *allowed,size_t count)
{if(!cJSON_IsObject(o))return false;for(const cJSON *c=o->child;c;c=c->next){bool found=false;for(size_t i=0;i<count;i++)if(strcmp(c->string,allowed[i])==0){found=true;break;}if(!found)return false;}return true;}
static bool number(const cJSON*n,double lo,double hi,double*out){if(!cJSON_IsNumber(n)||!isfinite(n->valuedouble)||n->valuedouble<lo||n->valuedouble>hi)return false;if(out)*out=n->valuedouble;return true;}
static bool integer(const cJSON*n,unsigned lo,unsigned hi,unsigned*out){double d=0;if(!number(n,lo,hi,&d)||floor(d)!=d)return false;if(out)*out=(unsigned)d;return true;}
static bool copy_string(const cJSON*n,char*out,size_t size,bool required){if(!n)return !required;if(!cJSON_IsString(n)||!n->valuestring||strlen(n->valuestring)>=size)return false;memcpy(out,n->valuestring,strlen(n->valuestring)+1U);return true;}
static bool parse_axis(const cJSON*o,motion_axis_calibration_t*a){static const char*const k[]={"minCode","centerCode","maxCode","deadzone"};unsigned u=0;double d=0;if(!keys(o,k,4)||!integer(item(o,k[0]),0,4095,&u))return false;a->min_code=(uint16_t)u;if(!integer(item(o,k[1]),0,4095,&u))return false;a->center_code=(uint16_t)u;if(!integer(item(o,k[2]),0,4095,&u))return false;a->max_code=(uint16_t)u;if(!number(item(o,k[3]),0,.5,&d))return false;a->deadzone=(float)d;return a->min_code<=a->center_code&&a->center_code<=a->max_code;}
static bool parse_gpio(const cJSON*o,motion_gpio_behavior_t*g){static const char*const k[]={"mode","activeLow"};if(!keys(o,k,2))return false;const cJSON*m=item(o,k[0]),*a=item(o,k[1]);if(!cJSON_IsString(m)||!cJSON_IsBool(a))return false;if(strcmp(m->valuestring,"pushPull")==0)g->mode=MOTION_GPIO_PUSH_PULL;else if(strcmp(m->valuestring,"openDrain")==0)g->mode=MOTION_GPIO_OPEN_DRAIN;else return false;g->active_low=cJSON_IsTrue(a);return true;}
static bool parse_stick(const cJSON*o,motion_stick_calibration_t*s){static const char*const k[]={"x","y","radialEnvelope","safetyFactor"};if(!keys(o,k,4)||!parse_axis(item(o,k[0]),&s->x)||!parse_axis(item(o,k[1]),&s->y))return false;const cJSON*e=item(o,k[2]);if(!cJSON_IsArray(e)||cJSON_GetArraySize(e)!=360)return false;for(int i=0;i<360;i++){double d=0;if(!number(cJSON_GetArrayItem(e,i),.000001,2,&d))return false;s->radial_envelope[i]=(float)d;}double f=0;if(!number(item(o,k[3]),.5,1,&f))return false;s->safety_factor=(float)f;return true;}
static bool parse_cell(const cJSON*o,learned_motion_cell_t*c){static const char*const k[]={"samples","velocityMean","accelerationMean","jerkMean","velocityPeak","accelerationPeak","jerkPeak"};if(!keys(o,k,7))return false;unsigned samples=0;double x[6]={0};if(!integer(item(o,k[0]),0,UINT32_MAX,&samples))return false;for(int i=0;i<6;i++)if(!number(item(o,k[i+1]),0,1e9,&x[i]))return false;if(x[3]<x[0]||x[4]<x[1]||x[5]<x[2])return false;c->samples=samples;c->v_sum=(float)(x[0]*samples);c->a_sum=(float)(x[1]*samples);c->j_sum=(float)(x[2]*samples);c->v_peak=(float)x[3];c->a_peak=(float)x[4];c->j_peak=(float)x[5];return true;}
esp_err_t motion_profile_load_json(const char *path,motion_profile_t *profile)
{
    if(!path||!profile)return ESP_ERR_INVALID_ARG; FILE*f=fopen(path,"rb");if(!f)return ESP_ERR_NOT_FOUND;
    if(fseek(f,0,SEEK_END)!=0){fclose(f);return ESP_FAIL;}long size=ftell(f);rewind(f);if(size<2||size>(long)MOTION_PROFILE_JSON_MAX_BYTES){fclose(f);return ESP_ERR_INVALID_SIZE;}
    char*text=malloc((size_t)size+1U);if(!text){fclose(f);return ESP_ERR_NO_MEM;}bool read_ok=fread(text,1,(size_t)size,f)==(size_t)size&&!ferror(f);fclose(f);text[size]='\0';if(!read_ok){free(text);return ESP_FAIL;}
    cJSON*root=cJSON_ParseWithLength(text,(size_t)size);free(text);if(!root)return ESP_ERR_INVALID_ARG;
    motion_profile_t p={0};bool ok=true;unsigned u=0;double d=0;
    static const char*const rk[]={"schemaVersion","profile","analog","calibration","motionModel","tuning"};ok=keys(root,rk,6)&&integer(item(root,"schemaVersion"),1,1,&u);if(ok)p.schema_version=u;
    const cJSON*meta=item(root,"profile");static const char*const mk[]={"id","name","description","createdUtc","modifiedUtc"};ok=ok&&keys(meta,mk,5)&&copy_string(item(meta,"id"),p.id,sizeof p.id,true)&&copy_string(item(meta,"name"),p.name,sizeof p.name,true)&&copy_string(item(meta,"description"),p.description,sizeof p.description,false);
    const cJSON*analog=item(root,"analog");static const char*const ak[]={"voltage","channels","sensorPower","faultLed"};ok=ok&&keys(analog,ak,4);const cJSON*vol=item(analog,"voltage");static const char*const vk[]={"adcFullScaleV","dacReferenceV","dacOutputMinV","dacOutputMaxV"};ok=ok&&keys(vol,vk,4);if(ok&&number(item(vol,vk[0]),.000001,5.5,&d))p.adc_full_scale_v=(float)d;else ok=false;if(ok&&number(item(vol,vk[1]),.000001,5.5,&d))p.dac_reference_v=(float)d;else ok=false;if(ok&&number(item(vol,vk[2]),0,5.5,&d))p.dac_output_min_v=(float)d;else ok=false;if(ok&&number(item(vol,vk[3]),.000001,5.5,&d))p.dac_output_max_v=(float)d;else ok=false;
    const cJSON*channels=item(analog,"channels");ok=ok&&cJSON_IsArray(channels)&&cJSON_GetArraySize(channels)==8;uint8_t logical_seen=0,adc_seen=0,dac_seen=0;const char*names[8]={"LX","LY","RX","RY","LT","RT","L2","R2"};static const char*const ck[]={"logical","dacChannel","adcChannel","neutralCode","safeCode","invert"};
    for(int i=0;ok&&i<8;i++){const cJSON*ch=cJSON_GetArrayItem(channels,i);ok=keys(ch,ck,6);const cJSON*ln=item(ch,"logical");int li=-1;if(cJSON_IsString(ln))for(int j=0;j<8;j++)if(strcmp(ln->valuestring,names[j])==0)li=j;if(li<0||(logical_seen&(1U<<li))){ok=false;break;}logical_seen|=1U<<li;motion_analog_channel_t*c=&p.channel[li];if(!integer(item(ch,"dacChannel"),0,7,&u)||(dac_seen&(1U<<u))){ok=false;break;}c->dac_channel=(uint8_t)u;dac_seen|=1U<<u;if(!integer(item(ch,"adcChannel"),0,7,&u)||(adc_seen&(1U<<u))){ok=false;break;}c->adc_channel=(uint8_t)u;adc_seen|=1U<<u;if(!integer(item(ch,"neutralCode"),0,4095,&u)){ok=false;break;}c->neutral_code=(uint16_t)u;if(!integer(item(ch,"safeCode"),0,4095,&u)){ok=false;break;}c->safe_code=(uint16_t)u;const cJSON*inv=item(ch,"invert");if(!cJSON_IsBool(inv)){ok=false;break;}c->invert=cJSON_IsTrue(inv);}
    ok=ok&&parse_gpio(item(analog,"sensorPower"),&p.sensor_power)&&parse_gpio(item(analog,"faultLed"),&p.fault_led);
    const cJSON*cal=item(root,"calibration");static const char*const calk[]={"leftStick","rightStick","triggers"};ok=ok&&keys(cal,calk,3)&&parse_stick(item(cal,"leftStick"),&p.left_stick)&&parse_stick(item(cal,"rightStick"),&p.right_stick);const cJSON*tr=item(cal,"triggers");const char*tn[4]={"LT","RT","L2","R2"};ok=ok&&keys(tr,tn,4);for(int i=0;ok&&i<4;i++)ok=parse_axis(item(tr,tn[i]),&p.trigger[i]);
    const cJSON*mm=item(root,"motionModel");static const char*const mmk[]={"angleBins","magnitudeBins","cells"};ok=ok&&keys(mm,mmk,3)&&integer(item(mm,"angleBins"),360,360,&u)&&integer(item(mm,"magnitudeBins"),4,4,&u);const cJSON*cells=item(mm,"cells");ok=ok&&cJSON_IsArray(cells)&&cJSON_GetArraySize(cells)==MOTION_MODEL_CELLS;p.learned.version=1;for(int i=0;ok&&i<MOTION_MODEL_CELLS;i++){ok=parse_cell(cJSON_GetArrayItem(cells,i),&p.learned.cell[i]);p.learned.total_samples+=p.learned.cell[i].samples;}
    const cJSON*t=item(root,"tuning");static const char*const tk[]={"velocityScale","accelerationScale","jerkScale","responseScale","deadzoneOverride","dampingOverride"};ok=ok&&keys(t,tk,6);float*dst[4]={&p.tuning.velocity_scale,&p.tuning.acceleration_scale,&p.tuning.jerk_scale,&p.tuning.response_scale};for(int i=0;ok&&i<4;i++){if(!number(item(t,tk[i]),.000001,10,&d))ok=false;else *dst[i]=(float)d;}const cJSON*dn=item(t,"deadzoneOverride"),*dm=item(t,"dampingOverride");if(ok){if(cJSON_IsNull(dn))p.tuning.deadzone_override=-1;else if(number(dn,0,.5,&d))p.tuning.deadzone_override=(float)d;else ok=false;}if(ok){if(cJSON_IsNull(dm))p.tuning.damping_override=-1;else if(number(dm,0,1,&d))p.tuning.damping_override=(float)d;else ok=false;}
    cJSON_Delete(root);if(!ok||motion_profile_validate(&p,NULL,0)!=ESP_OK)return ESP_ERR_INVALID_ARG;*profile=p;return ESP_OK;
}
